    F32,
    BF16,
};

struct MFMAConfig {
    llvm::StringRef name;
    int64_t m;
    int64_t n;
    int64_t k;
    llvm::StringRef typeA;
    llvm::StringRef typeC;
    llvm::StringRef intrinsic;
    VectorElemKind aElem;
